CREATE TABLE auth_user(id text PRIMARY KEY,name text NOT NULL,email text NOT NULL UNIQUE,"emailVerified" boolean NOT NULL DEFAULT false,image text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_session(id text PRIMARY KEY,"userId" text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE,token text NOT NULL UNIQUE,"expiresAt" timestamptz NOT NULL,"ipAddress" text,"userAgent" text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX auth_session_user_idx ON auth_session("userId");
CREATE TABLE auth_account(id text PRIMARY KEY,"userId" text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE,"accountId" text NOT NULL,"providerId" text NOT NULL,"accessToken" text,"refreshToken" text,"accessTokenExpiresAt" timestamptz,"refreshTokenExpiresAt" timestamptz,scope text,"idToken" text,password text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),UNIQUE("providerId","accountId"));
CREATE INDEX auth_account_user_idx ON auth_account("userId");
CREATE TABLE auth_verification(id text PRIMARY KEY,identifier text NOT NULL,value text NOT NULL,"expiresAt" timestamptz NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX auth_verification_identifier_idx ON auth_verification(identifier);
CREATE TABLE account_workspaces(user_id text PRIMARY KEY REFERENCES auth_user(id) ON DELETE RESTRICT,workspace_id uuid NOT NULL UNIQUE REFERENCES workspaces(id) ON DELETE RESTRICT);
CREATE TABLE planned_integrations(workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT,integration_key text NOT NULL,provider_key text NOT NULL,environment text NOT NULL,setup jsonb NOT NULL,configured boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,integration_key,provider_key,environment));
